process STRVCTVRE_STRVCTVRE {
    tag "$meta.id"
    label 'process_low'

    conda "${moduleDir}/environment.yml"
    container "${ workflow.containerEngine in ['singularity', 'apptainer'] && !task.ext.singularity_pull_docker_container ?
        'https://community-cr-prod.seqera.io/docker/registry/v2/blobs/sha256/95/9584eeb6569a511be29d0a07bf80103d59d38715ddb971dddeca0bc72aec41d3/data':
        'community.wave.seqera.io/library/liftover_strvctvre:5fec172b808cc48e' }"

    input:
    tuple val(meta), path(sv_file), path(sv_file_index), val(assembly)
    tuple val(meta2), path(phylop)
    tuple val(meta3), path(data_directory)

    output:
    tuple val(meta), path("*.vcf"), emit: vcf, optional: true
    tuple val(meta), path("*.bed"), emit: bed, optional: true
    tuple val("${task.process}"), val('strvctvre'), eval("StrVCTVRE.py --help |& sed -n 's/StrVCTVRE: version *//p'"), emit: versions_strvctvre, topic: versions

    when:
    task.ext.when == null || task.ext.when

    script:
    def prefix = task.ext.prefix ?: "${meta.id}"
    def format = ''
    if (sv_file.name.endsWith('.vcf') || sv_file.name.endsWith('.vcf.gz')) {
        format = 'vcf'
    } else if (sv_file.name.endsWith('.bed')) {
        format = 'bed'
    } else {
        error("Input structural variants file must be in VCF or BED format")
    }
    if (!['GRCh38', 'GRCh37'].contains(assembly)) {
        error("Assembly must be either 'GRCh37' or 'GRCh38'")
    }
    """
    StrVCTVRE.py \\
        --input ${sv_file} \\
        --format ${format} \\
        --phyloP ${phylop} \\
        --assembly ${assembly} \\
        --liftover liftover_hg19_to_hg38_public.py \\
        --output ${prefix}.${format}
    """

    stub:
    def prefix = task.ext.prefix ?: "${meta.id}"
    def format = ''
    if (sv_file.name.endsWith('.vcf') || sv_file.name.endsWith('.vcf.gz')) {
        format = 'vcf'
    } else if (sv_file.name.endsWith('.bed')) {
        format = 'bed'
    } else {
        error("Input structural variants file must be in VCF or BED format")
    }
    if (!['GRCh38', 'GRCh37'].contains(assembly)) {
        error("Assembly must be either 'GRCh37' or 'GRCh38'")
    }
    """
    touch ${prefix}.${format}
    """
}

nextflow_process {

    name "Test Process STRVCTVRE_STRVCTVRE"
    script "../main.nf"
    process "STRVCTVRE_STRVCTVRE"

    tag "modules"
    tag "modules_nfcore"
    tag "strvctvre"
    tag "strvctvre/strvctvre"

    // Only stub tests because of the big dependencies

    test("homo_sapiens - vcf - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/vcf/sv_query.vcf.gz', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/vcf/sv_query.vcf.gz.tbi', checkIfExists: true),
                    "GRCh38"
                ]
                input[1] = [
                    [ id: 'ref' ],
                    []
                ]
                input[2] = [
                    [ id: 'data' ],
                    []
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }

    test("homo_sapiens - bed - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.bed', checkIfExists: true),
                    [],
                    "GRCh38"
                ]
                input[1] = [
                    [ id: 'ref' ],
                    []
                ]
                input[2] = [
                    [ id: 'data' ],
                    []
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }

}

